import json
from pathlib import Path
L=lambda a,b: {'en':a,'id':b}
cases=[]
def case(n,title,titleid,kind,kindid,setting,settingid,brief,briefid,scenes,scenesid,chars,solution,solutionid):
 c=dict(id=n,title=L(title,titleid),kind=L(kind,kindid),setting=L(setting,settingid),brief=L(brief,briefid),difficulty=0 if (n-1)%6<2 else 1 if (n-1)%6<4 else 2,scenes=[L(a,b) for a,b in zip(scenes.split('|'),scenesid.split('|'))],characters=[],evidence=[],questions=[],solution=L(solution,solutionid));cases.append(c)
 for name,role,roleid,age,claim,claimid,fact,factid in chars:
  c['characters'].append(dict(id=f'c{n}-{len(c["characters"])}',name=name,role=L(role,roleid),age=age,background=L(claim,claimid),responses=[L(claim,claimid),L(fact,factid),L('My recollection is a lead. Compare it with the records before drawing a conclusion.','Ingatan saya hanya petunjuk awal. Bandingkan dengan catatan sebelum menarik kesimpulan.'),L('I have provided everything I can verify. The documents can establish what my memory cannot.','Saya sudah memberikan semua yang bisa saya pastikan. Dokumen dapat memastikan hal yang tidak bisa dijamin oleh ingatan saya.')]))
 return c
def ev(c,title,tid,body,bid,correct,corid,wrong):
 i=len(c['evidence']); c['evidence'].append(dict(id=f'E{c["id"]:02}-{i+1:02}',title=L(title,tid),body=L(body,bid),source=L(['Scene documentation','Certified records','Recorded interview','Laboratory report'][i%4],['Dokumentasi lokasi','Catatan terverifikasi','Wawancara terekam','Laporan laboratorium'][i%4]),stage=min(len(c['scenes'])-1,i*len(c['scenes'])//([10,10,14,14,18,18,12,12,16,16,20,20,12,12,16,16,20,20,14,14,16,16,20,22][c['id']-1]))))
 if i < [8,8,12,12,16,16,8,8,12,12,16,16,8,8,12,12,16,16,8,8,12,12,16,16][c['id']-1]:
  opts=[L(correct,corid)]+[L(a,b) for a,b in wrong]
  shift=(i+c['id'])%4;opts=opts[shift:]+opts[:shift]
  c['questions'].append(dict(id=f'Q{c["id"]}-{i}',stage=c['evidence'][-1]['stage'],refs=[c['evidence'][-1]['id']],prompt=L('Which inference is best supported by '+title.lower()+'?','Kesimpulan mana yang paling didukung oleh '+tid.lower()+'?'),options=opts,answer=(4-shift)%4,hints=[L('Separate the recorded observation from an explanation. What does this source actually establish?','Pisahkan pengamatan yang tercatat dari penjelasannya. Apa yang benar-benar dapat dipastikan dari sumber ini?'),L('Compare the exact wording and timing. Avoid a claim stronger than the evidence.','Bandingkan kata-kata dan waktunya dengan teliti. Hindari klaim yang melampaui bukti.')],explanation=L(correct,corid)))
def final(c,p,pid,options,correct,exp,expid):
 c['questions'].append(dict(id=f'F{c["id"]}-{len(c["questions"])}',stage=len(c['scenes']),refs=[e['id'] for e in c['evidence'][-3:]],prompt=L(p,pid),options=[L(a,b) for a,b in options],answer=correct,hints=[L('Return to the evidence that distinguishes your theory from its strongest alternative.','Periksa kembali bukti yang membedakan teori kamu dari alternatif terkuatnya.')],explanation=L(exp,expid)))
# Case 001: canonical model precedes evidence.
